// Oracle frozen before execution in tests/fixtures/h6-002/expected.json.
import {before,after,test} from 'node:test';
import assert from 'node:assert/strict';
import {randomUUID as uid,createHash} from 'node:crypto';
import {readFile} from 'node:fs/promises';
import {isolatedWork,read,write} from '../support/h6-current-isolated.ts';
import {directFixture} from '../support/h6-002-direct-fixture.ts';
import {verifyAuth} from '../../src/application/verified-auth.ts';
import {H0005PostgresAdapter} from '../../src/infrastructure/postgres/h0-005-adapter.ts';
import {H2009BookingAdapter,type BookingCommand} from '../../src/infrastructure/postgres/h2-booking-adapter.ts';
let h:Awaited<ReturnType<typeof isolatedWork>>;
type F=Awaited<ReturnType<typeof directFixture>>;
const run=async(f:F,q=f.q,stages=f.stages)=>h.booking.direct(await h.auth(),write,stages,q);
async function snapshot(){const o:Record<string,unknown>={};for(const {tablename:t} of await h.observer`select tablename from pg_tables where schemaname='crm_private' order by tablename`)o[t]=(await h.observer.unsafe(`select coalesce(jsonb_agg(to_jsonb(x) order by to_jsonb(x)::text),'[]') d from crm_private.${t} x`))[0]!.d;return o;}
const count=async(id:string)=>(await h.observer`select count(*)::int n from crm_private.b04_bookings where opportunity_id=${id}::uuid`)[0]!.n;
async function noEffect(fn:()=>Promise<unknown>){const old=await snapshot();await assert.rejects(fn);assert.deepEqual(await snapshot(),old);}
async function complete(f:F){const r=await run(f),out=await h.booking.read(await h.auth(),read,r.id) as any;assert.equal(r.id,f.q.bookingId);assert.equal(out.booking.state,'Pendiente de preparación');assert.equal(out.booking.opportunity_id,f.opportunityId);assert.equal(out.booking.acceptance_id,f.acceptanceId);assert.deepEqual(out.booking.terms,f.terms);assert.equal(out.booking.chain_snapshot.acceptance.accepter_id,f.accepterId);assert.equal(out.booking.chain_snapshot.acceptance.actor_id,h.actorId);assert.ok(out.history.length);assert.equal(await count(f.opportunityId),1);return out;}
before(async()=>{const b=await readFile('tests/fixtures/h6-002/expected.json');assert.equal(createHash('sha256').update(b).digest('hex'),(await readFile('tests/fixtures/h6-002/expected.json.sha256','utf8')).split(' ')[0]);h=await isolatedWork('crm_h6002_integrated',61101);});
after(async()=>{await h?.close();});
test('H6002 F01 direct minimal T01 T02 T03 chain exact terms/actor/acceptance; no Lead or fictitious sends',async t=>{const f=await directFixture(h);assert.equal((await h.observer`select count(*)::int n from crm_private.b03_proposals where opportunity_id=${f.opportunityId}::uuid`)[0]!.n,0);const out=await complete(f);assert.equal((await h.observer`select lead_id from crm_private.b03_opportunities where opportunity_id=${f.opportunityId}::uuid`)[0]!.lead_id,null);assert.equal((await h.observer`select count(*)::int n from crm_private.b03_leads`)[0]!.n,0);assert.equal((await h.observer`select count(*)::int n from crm_private.b03_offer_operations where proposal_id=${f.proposalId}::uuid and action='send'`)[0]!.n,0);t.diagnostic(JSON.stringify({bookingId:out.booking.booking_id,opportunityId:f.opportunityId,acceptanceId:f.acceptanceId,actor:h.actorId,accepter:f.accepterId,terms:f.terms,history:out.history.length}));});
test('H6002 F02 preparation without Acceptance persists; conversion rejected atomically',async()=>{const f=await directFixture(h);await h.proposal.apply(await h.auth(),write,f.prepare);await h.proposal.apply(await h.auth(),write,f.fix);await h.offer.apply(await h.auth(),write,f.issue);await noEffect(async()=>h.booking.apply(await h.auth(),write,{...f.q,expectedRevision:3,expectedOpportunityRevision:2}));assert.equal(await count(f.opportunityId),0);assert.equal((await h.observer`select count(*)::int n from crm_private.b03_proposal_versions where version_id=${f.versionId}::uuid`)[0]!.n,1);assert.equal((await h.observer`select count(*)::int n from crm_private.b03_acceptances where acceptance_id=${f.acceptanceId}::uuid`)[0]!.n,0);});
test('H6002 F03 registered unverified acceptance cannot substitute client verification; no opinion/AI invented acceptance',async()=>{const f=await directFixture(h);await noEffect(()=>run(f,f.q,f.stages.slice(0,4)));await noEffect(()=>run(f,{...f.q,origin:'ai'}));assert.equal(await count(f.opportunityId),0);});
test('H6002 F04 existing real chain reused; exact replay and lost-response recovery preserve all protected state',async()=>{const f=await directFixture(h);await run(f);const before=await snapshot();delete before.identification_epochs;const r=await h.booking.apply(await h.auth(),write,f.q);assert.equal(r.replayed,true);assert.equal(r.id,f.q.bookingId);const after=await snapshot();delete after.identification_epochs;assert.deepEqual(after,before);const rr=await run(f);assert.equal(rr.id,f.q.bookingId);const final=await snapshot();delete final.identification_epochs;assert.deepEqual(final,before);});
test('H6002 F05 changed material replay and split/merge denied even with valid agreement',async()=>{const f=await directFixture(h);await run(f);for(const extra of [{reason:'H6002 changed material'},{split:true},{mergeOpportunityId:uid()}])await noEffect(async()=>h.booking.apply(await h.auth(),write,{...f.q,...extra} as BookingCommand));});
test('H6002 F06 late deferred commit fault rolls T01 T02 T03 back, then recovery has one complete chain',async()=>{const f=await directFixture(h),old=await snapshot();await h.admin.unsafe(`create function crm_private.h6002_fault() returns trigger language plpgsql as $$begin raise exception 'H6002_SYNTHETIC_FAULT';end$$;create constraint trigger h6002_fault after insert on crm_private.b04_history deferrable initially deferred for each row execute function crm_private.h6002_fault()`);try{await assert.rejects(run(f));assert.deepEqual(await snapshot(),old);}finally{await h.admin.unsafe('drop trigger h6002_fault on crm_private.b04_history;drop function crm_private.h6002_fault()');}await complete(f);});
test('H6002 F07 two authenticated sessions races exact and equivalent distinct keys both dispatch orders',async t=>{const first=await verifyAuth({verify:async()=>({subject:h.subject,passwordVerified:true,mfaVerified:true})},uid()),sessionId=(await new H0005PostgresAdapter(h.runtime,h.f1,h.f2).establish(first)).sessionId,second=await verifyAuth({verify:async()=>({subject:h.subject,sessionId,passwordVerified:true,mfaVerified:true})},uid());for(const distinct of [false,true])for(const reverse of [false,true]){const f=await directFixture(h);for(const stage of f.stages){if(stage.kind==='proposal')await h.proposal.apply(await h.auth(),write,stage.command);else if(stage.kind==='offer')await h.offer.apply(await h.auth(),write,stage.command);else if(stage.kind==='acceptance')await h.acceptance.apply(await h.auth(),write,stage.command);}const other=distinct?{...f.q,operationId:uid(),bookingId:uid()}:f.q,auth=await h.auth(),actions=[()=>h.booking.apply(auth,write,f.q),()=>h.booking.apply(second,write,other)];if(reverse)actions.reverse();const r=await Promise.all(actions.map(a=>a()));assert.equal(r[0]!.id,r[1]!.id);assert.equal(await count(f.opportunityId),1);t.diagnostic(JSON.stringify({distinct,reverse,bookingId:r[0]!.id,secondSession:true}));}});
test('H6002 F08 conflicting operations same root both orders yield one winner, no second Booking',async()=>{for(const reverse of [false,true]){const f=await directFixture(h);await run(f);const a={...f.q,operationId:uid(),bookingId:uid()},b={...a,operationId:uid(),bookingId:uid(),reason:'H6002 incompatible effect'};const requests=reverse?[b,a]:[a,b],out=await Promise.allSettled(requests.map(async q=>h.booking.apply(await h.auth(),write,q)));assert.equal(out.filter(x=>x.status==='fulfilled').length,1);assert.equal(await count(f.opportunityId),1);}});
test('H6002 F09 error-attribution rectification retains original/terms/moments/actor and current dependent reevaluation, no external reversal',async t=>{const f=await directFixture(h);const out=await complete(f);const original=(await h.observer`select to_jsonb(a) d from crm_private.b03_acceptances a where acceptance_id=${f.acceptanceId}::uuid`)[0]!.d;const at=new Date().toISOString(),evidenceId=await f.proof(`acceptance:error:${f.acceptanceId}`,at),review=await f.proof(`acceptance:reevaluate:${f.acceptanceId}:Necesidad definida`,at);await h.acceptance.apply(await h.auth(),write,{...f.register,action:'rectify',operationId:uid(),expectedRevision:5,expectedOpportunityRevision:3,at,evidenceId,humanReviewed:true,reevaluation:{destination:'Necesidad definida',evidenceId:review,dependentEffects:['verification','commercial']}});assert.deepEqual((await h.observer`select to_jsonb(a) d from crm_private.b03_acceptances a where acceptance_id=${f.acceptanceId}::uuid`)[0]!.d,original);const a=await h.acceptance.read(await h.auth(),read,f.proposalId,f.versionId) as any;assert.ok(JSON.stringify(a).includes(f.acceptanceId));assert.ok(JSON.stringify(a).includes(evidenceId));assert.ok(JSON.stringify(a).includes('Necesidad definida'));const b=await h.booking.read(await h.auth(),read,f.q.bookingId) as any;assert.deepEqual(b.booking.chain_snapshot,out.booking.chain_snapshot);assert.equal(await count(f.opportunityId),1);await noEffect(async()=>h.booking.apply(await h.auth(),write,{...f.q,bookingId:uid(),operationId:uid(),reason:'new conversion after rectification'}));t.diagnostic(JSON.stringify({original,acceptanceReadback:a,bookingSnapshotPreserved:true}));});
test('H6002 F10 rectification without accredited error/review denied; immutable original protected from runtime SQL',async()=>{const f=await directFixture(h);await run(f);await noEffect(async()=>h.acceptance.apply(await h.auth(),write,{...f.register,action:'rectify',operationId:uid(),expectedRevision:5,expectedOpportunityRevision:3,humanReviewed:true}));await noEffect(()=>h.runtime`update crm_private.b03_acceptances set terms='{}' where acceptance_id=${f.acceptanceId}::uuid`);await noEffect(()=>h.runtime`update crm_private.b03_proposal_versions set content='{}' where version_id=${f.versionId}::uuid`);});
test('H6002 F11 no context, forged evidence, disabled actor, role and cross-scope reads/replays denied',async()=>{const f=await directFixture(h);await run(f);const ordinary=h.connect('authenticated');await assert.rejects(ordinary`select * from crm_private.b04_bookings`);await assert.rejects(h.runtime`select * from crm_private.b04_bookings`);await noEffect(async()=>h.booking.apply({...await h.auth()} as never,write,f.q));const stranger=await verifyAuth({verify:async()=>({subject:uid(),sessionId:uid(),passwordVerified:true,mfaVerified:true})},uid());await noEffect(()=>h.booking.apply(stranger,write,f.q));await assert.rejects(h.booking.read(stranger,read,f.q.bookingId));await h.migration`update crm_private.crm_actors set enabled=false where actor_id=${h.actorId}::uuid`;try{await assert.rejects(h.booking.apply(await h.auth(),write,f.q));await assert.rejects(h.booking.read(await h.auth(),read,f.q.bookingId));}finally{await h.migration`update crm_private.crm_actors set enabled=true where actor_id=${h.actorId}::uuid`;}await h.migration`update crm_private.crm_actors set admin_scope='H6002-OTHER-SCOPE' where actor_id=${h.actorId}::uuid`;try{const subject=h.subject,auth0=await verifyAuth({verify:async()=>({subject,passwordVerified:true,mfaVerified:true})},uid()),sessionId=(await new H0005PostgresAdapter(h.runtime,h.f1,h.f2).establish(auth0)).sessionId,other=await verifyAuth({verify:async()=>({subject,sessionId,passwordVerified:true,mfaVerified:true})},uid());assert.equal(await h.booking.read(other,read,f.q.bookingId),null);await noEffect(()=>h.booking.apply(other,write,f.q));}finally{await h.migration`update crm_private.crm_actors set admin_scope=${h.scope} where actor_id=${h.actorId}::uuid`;}assert.ok(await h.booking.read(await h.auth(),read,f.q.bookingId));});
test('H6002 F12 Ganada+Acceptance never imply payment, confirmation or fiscal emission; forbidden fields attempted',async()=>{const f=await directFixture(h);await noEffect(()=>run(f,{...f.q,state:'Confirmada',paymentState:'Conciliado'} as BookingCommand));await complete(f);for(const table of ['b05_movements','b05_provider_invoices','b05_provider_payments','b06_joint_closures'])if((await h.observer`select to_regclass(${'crm_private.'+table}) r`)[0]!.r)assert.equal((await h.observer.unsafe(`select count(*)::int n from crm_private.${table}`))[0]!.n,0);assert.equal((await h.observer`select state from crm_private.b04_services where booking_id=${f.q.bookingId}::uuid`)[0]!.state,'Pendiente');});

test('H6002 F13 observed overlapping root lock with two sessions, no prior Booking and incompatible commands in both orders',async t=>{const first=await verifyAuth({verify:async()=>({subject:h.subject,passwordVerified:true,mfaVerified:true})},uid()),sessionId=(await new H0005PostgresAdapter(h.runtime,h.f1,h.f2).establish(first)).sessionId,second=await verifyAuth({verify:async()=>({subject:h.subject,sessionId,passwordVerified:true,mfaVerified:true})},uid());for(const reverse of [false,true]){const f=await directFixture(h);for(const stage of f.stages){if(stage.kind==='proposal')await h.proposal.apply(await h.auth(),write,stage.command);else if(stage.kind==='offer')await h.offer.apply(await h.auth(),write,stage.command);else if(stage.kind==='acceptance')await h.acceptance.apply(await h.auth(),write,stage.command);}assert.equal(await count(f.opportunityId),0);let unlock!:()=>void,ready!:()=>void;const gate=new Promise<void>(r=>unlock=r),locked=new Promise<void>(r=>ready=r);const holding=h.admin.begin(async tx=>{await tx`select opportunity_id from crm_private.b03_opportunities where opportunity_id=${f.opportunityId}::uuid for update`;ready();await gate;});await locked;const a=await h.auth(),q={...f.q,operationId:uid(),bookingId:uid(),reason:'H6002 competing incompatible detail'};let actions=[()=>h.booking.apply(a,write,f.q),()=>h.booking.apply(second,write,q)];if(reverse)actions.reverse();const pending=Promise.allSettled(actions.map(x=>x()));let blocked=0;try{for(let i=0;i<100;i++){blocked=(await h.observer`select count(*)::int n from pg_stat_activity where datname=current_database() and usename='crm_h0_runtime' and wait_event_type='Lock'`)[0]!.n;if(blocked>=2)break;await new Promise(r=>setTimeout(r,10));}assert.ok(blocked>=2,'both independent sessions must overlap while root held');}finally{unlock();await holding;}const out=await pending;assert.equal(out.filter(x=>x.status==='fulfilled').length,1);assert.equal(await count(f.opportunityId),1);t.diagnostic(JSON.stringify({reverse,blockedSessions:blocked,oneWinner:true,bookings:1}));}});
test('H6002 F14 injected lost application response after actual commit recovers existing identity',async()=>{const f=await directFixture(h);const dropped={begin:async(...args:any[])=>{await (h.runtime.begin as any)(...args);throw Error('H6002_LOST_RESPONSE_AFTER_COMMIT');}};const adapter=new H2009BookingAdapter(dropped as never,h.f1,h.f2);await assert.rejects(adapter.direct(await h.auth(),write,f.stages,f.q),/H6002_LOST_RESPONSE_AFTER_COMMIT/);assert.equal(await count(f.opportunityId),1);const r=await run(f);assert.equal(r.id,f.q.bookingId);assert.equal(r.replayed,true);assert.equal(await count(f.opportunityId),1);});
